<?php require_once __DIR__.'/../config.php';require_student();$pageTitle='Admission application';$error='';$programmes=['B.Tech - Computer Science & Engineering','B.Tech - Electronics & Communication','BBA - Business Administration','BCA - Computer Applications','B.Sc - Mathematics','B.Sc - Physics','BA - English'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$dob=$_POST['dob']??'';$gender=$_POST['gender']??'';$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$programme=$_POST['programme']??'';$qualification=trim($_POST['qualification']??'');$percentage=$_POST['percentage']??'';$year=$_POST['passing_year']??'';$fileName=null;if(!$name||!$dob||!$phone||!$address||!in_array($programme,$programmes,true)||!$qualification||!is_numeric($percentage)||$percentage<0||$percentage>100||!preg_match('/^\d{4}$/',(string)$year)){$error='Please complete all required fields with valid information.';}else{if(!empty($_FILES['document']['name'])){$f=$_FILES['document'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!in_array($ext,['pdf','jpg','jpeg','png'],true)){$error='Document must be a PDF, JPG or PNG file under 2 MB.';}else{$fileName='doc_'.current_user()['id'].'_'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],UPLOAD_DIR.$fileName)){$fileName=null;$error='Could not upload the document. Please try again.';}}}if(!$error){$q=db()->prepare('INSERT INTO applications(user_id,full_name,dob,gender,phone,address,programme,qualification,percentage,passing_year,document,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,\'Pending\')');$q->execute([current_user()['id'],$name,$dob,$gender,$phone,$address,$programme,$qualification,$percentage,$year,$fileName]);flash('success','Your admission application has been submitted successfully.');redirect('student/dashboard.php');}}}require __DIR__.'/../includes/header.php';?>
<section class="form-page"><div class="container"><div class="form-shell wide"><div class="eyebrow">Student admission</div><h1>Application form</h1><p class="form-intro">Enter accurate details. Fields marked with * are required.</p><?php if($error): ?><div class="alert error" style="width:100%;margin:0 0 15px"><?= e($error) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><h3>Personal information</h3><div class="form-row"><div class="field"><label>Full name *</label><input name="full_name" required value="<?= e($_POST['full_name']??current_user()['name']) ?>"></div><div class="field"><label>Date of birth *</label><input type="date" name="dob" required max="<?= date('Y-m-d') ?>" value="<?= e($_POST['dob']??'') ?>"></div></div><div class="form-row"><div class="field"><label>Gender</label><select name="gender"><option value="">Select</option><?php foreach(['Female','Male','Other','Prefer not to say'] as $g): ?><option <?= (($_POST['gender']??'')===$g?'selected':'') ?>><?= e($g) ?></option><?php endforeach; ?></select></div><div class="field"><label>Phone number *</label><input name="phone" required value="<?= e($_POST['phone']??'') ?>"></div></div><div class="field"><label>Address *</label><textarea name="address" required><?= e($_POST['address']??'') ?></textarea></div><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>Academic information</h3><div class="field"><label>Preferred programme *</label><select name="programme" required><option value="">Choose a programme</option><?php foreach($programmes as $p): ?><option value="<?= e($p) ?>" <?= (($_POST['programme']??'')===$p?'selected':'') ?>><?= e($p) ?></option><?php endforeach; ?></select></div><div class="form-row"><div class="field"><label>Last qualification *</label><input name="qualification" required placeholder="e.g. Higher Secondary" value="<?= e($_POST['qualification']??'') ?>"></div><div class="field"><label>Percentage / marks (%) *</label><input type="number" name="percentage" min="0" max="100" step="0.01" required value="<?= e($_POST['percentage']??'') ?>"></div></div><div class="form-row"><div class="field"><label>Year of passing *</label><input type="number" name="passing_year" min="1980" max="<?= date('Y') ?>" required value="<?= e($_POST['passing_year']??'') ?>"></div><div class="field"><label>Upload marksheet (optional)</label><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png"><div class="file-note">PDF, JPG or PNG · Maximum size 2 MB</div></div></div><div class="notice">Please review your information before submitting. Your application will be marked as Pending until reviewed by the admissions team.</div><button class="btn form-submit">Submit application</button></form></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
